	public bool HideEffectValue => hideEffectValue;

	public ProtectionHollowSkinEnum NegatableByEffectEnum => negatableByEffectEnum;

	public Effect[] ExtraEffects => extraEffects;

	public Tag[] Tags => tags;

	public ActionFaceForDescription[] ActionFaceForDescriptions => actionFaceForDescriptions;

	public bool EnableGainEffectSFX => enableGainEffectSFX;

	public bool DisableGainEffectSFX => disableGainEffectSFX;

	public bool ShowOnModSentinelEffectsList => showOnModSentinelEffectsList;

	public bool Mute => mute;

	protected bool isOnBattleScene => GameScenesUtils.IsBattleScene();

	protected LocalizationManager localizationManager => ReferenceSingleton<LocalizationManager>.Instance;

	public virtual string GetEffectName()
	{
		string text = "";
		text = ((!enableCustomActionIDNameForDescription) ? (EffectID + "_N") : customActionIDNameForDescription);
		return localizationManager.GetLocalizedString(text);
	}

	public virtual string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		text = ((amount != EffectsValues.NO_VALUE && amount != -1) ? GetEffectDescriptionWithAmount(amount, effectOwner) : GetEffectDescriptionWithAmountReplacedWithX(GetLocalizedDescription(), amount, effectOwner));
		return text + AppendedDescription();
	}

	protected virtual string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		if (localizedDescription.Contains("{0"))
		{
			localizedDescription = Smart.Format(localizedDescription, GetNumberToReplaceWithX());
			localizedDescription = FormattedDescriptionReplacedWithX(localizedDescription);
		}
		return localizedDescription;
	}

	protected int GetNumberToReplaceWithX()
	{
		return 9999999;
	}

	protected string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, object firstArgument, object secondArgument)
	{
		localizedDescription = Smart.Format(localizedDescription, firstArgument, secondArgument);
		return FormattedDescriptionReplacedWithX(localizedDescription);
	}

	protected string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, object firstArgument, object secondArgument, object thirdArgument)
	{
		localizedDescription = Smart.Format(localizedDescription, firstArgument, secondArgument, thirdArgument);
		return FormattedDescriptionReplacedWithX(localizedDescription);
	}

	protected string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, object firstArgument, object secondArgument, object thirdArgument, object fourthArgument)
	{
		localizedDescription = Smart.Format(localizedDescription, firstArgument, secondArgument, thirdArgument, fourthArgument);
		return FormattedDescriptionReplacedWithX(localizedDescription);
	}

	protected string FormattedDescriptionReplacedWithX(string localizedDescription)
	{
		return localizedDescription.Replace(GetNumberToReplaceWithX().ToString(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedX());
	}

	protected virtual string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount);
	}

	public string GetLocalizedDescriptionExternal()
	{
		return GetLocalizedDescription();
	}

	protected virtual string GetLocalizedDescription()
	{
		string text = "";
		text = ((!enableCustomEffectDescriptionID) ? (EffectID + "_D") : customEffectDescriptionID);
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(text);
	}

	protected virtual string AppendedDescription()
	{
		if (appendDecreaseEffectDescription == AppendDecreaseEffectDescription.ENDOFPLAYERTURN)
		{
			return "\n" + DecreaseEffectLocalizedDescription(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAtTheEndOfYourTurn(withSpace: true));
		}
		if (appendDecreaseEffectDescription == AppendDecreaseEffectDescription.STARTOFYOURTURN)
		{
			return "\n" + DecreaseEffectLocalizedDescription(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAtTheStartOfYourTurn(withSpace: true));
		}
		return "";
	}

	protected string DecreaseEffectLocalizedDescription(string initialLocalizedText)
	{
		string text = "";
		text = ((!decreaseByHalfEffectDescription) ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDecreaseEffect(this, 1).LowercaseFirst() : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedDecreaseEffectDecreaseByHalf(this).LowercaseFirst());
		return initialLocalizedText + text;
	}

	public virtual void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
	}

	public virtual void InitializeCompendium(int effectAmount, GameObject effectOwner)
	{
	}

	public void InitializeVFX(GameObject effectOwner, bool gainingEffectVFXAndSFX)
	{
		if (initializeVFXSpawn)
		{
			InitializeVFXSpawn(effectOwner, gainingEffectVFXAndSFX);
		}
		else if (initializeVFXSpawnLoopingAndStoreOnRemoval)
		{
			if (!IsVFXEnabled())
			{
				return;
			}
			if (enableLoopingVFXSpawnDelay)
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, loopingVFXSpawnDelay, delegate
				{
					SpawnInitializeVFXLooping(effectOwner, firstVFX: true);
				});
			}
			else
			{
				SpawnInitializeVFXLooping(effectOwner, firstVFX: true);
			}
		}
		else
		{
			if (!initializeVFXSpawnAndVFXLoopingStoreOnRemoval)
			{
				return;
			}
			InitializeVFXSpawn(effectOwner, gainingEffectVFXAndSFX);
			if (!IsSecondVFXEnabled())
			{
				return;
			}
			if (enableLoopingVFXSpawnDelay)
			{
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, loopingVFXSpawnDelay, delegate
				{
					SpawnInitializeVFXLooping(effectOwner, firstVFX: false);
				});
			}
			else
			{
				SpawnInitializeVFXLooping(effectOwner, firstVFX: false);
			}
		}
	}

	private void InitializeVFXSpawn(GameObject effectOwner, bool gainingEffectVFXAndSFX)
	{
		if (enableInitializedVFXSpawnDelay)
		{
			if (ignoreInitializedVFXSpawnDelayOnInitializeGameState && ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.InitializeBattleState)
			{
				SpawnInitializeVFX(effectOwner, gainingEffectVFXAndSFX);
				return;
			}
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, initializedVFXSpawnDelay, delegate
			{
				SpawnInitializeVFX(effectOwner, gainingEffectVFXAndSFX);
			});
		}
		else
		{
			SpawnInitializeVFX(effectOwner, gainingEffectVFXAndSFX);
		}
	}

	private void SpawnInitializeVFX(GameObject effectOwner, bool gainingEffectVFXAndSFX)
	{
		if (gainingEffectVFXAndSFX)
		{
			SpawnVFX(GetVFXOwnerPosition(effectOwner), 5f);
		}
	}

	private void SpawnInitializeVFXLooping(GameObject effectOwner, bool firstVFX)
	{
		GameObject gameObject = null;
		gameObject = ((!firstVFX) ? GetSecondVFX(GetVFXOwnerPosition(effectOwner)) : GetVFX(GetVFXOwnerPosition(effectOwner)));
		ReferenceSingleton<VFXHandler>.Instance.AddToVFXHolders(new VFXHolder(effectOwner, this, gameObject));
		gameObject.GetComponent<ParticleEmissionController>().SetActive(value: true);
	}

	public virtual void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
	}

	public void EffectIncreasedSpawnVFX(GameObject effectOwner, bool gainingEffectVFXAndSFX)
	{
		if (effectIncreasedUseInitializeSpawnVFX)
		{
			SpawnInitializeVFX(effectOwner, gainingEffectVFXAndSFX);
		}
	}

	public virtual void EffectDecreased(int effectAmount, GameObject effectOwner)
	{
	}

	public virtual int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		return -1;
	}

	public virtual int OptionalActivateEffect(int effectAmount, GameObject effectOwner)
