		return -1;
	}

	public virtual int ActivateEffectWithPurifyAmountAndSource(int effectAmount, GameObject effectOwner, int purifyAmount, GameObject source)
	{
		return -1;
	}

	public virtual int ActivateEffectWithCorruptAmountAndSource(int effectAmount, GameObject effectOwner, int corruptAmount, GameObject source)
	{
		return -1;
	}

	public virtual int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
