	public virtual void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		RemoveConstantVFX(effectOwner);
	}

	public virtual void OnRemoveEffectEndOfBattle(int effectAmount, GameObject effectOwner)
	{
		RemoveConstantVFX(effectOwner);
	}

	public void RemoveConstantVFX(GameObject effectOwner)
	{
		if (initializeVFXSpawnLoopingAndStoreOnRemoval || initializeVFXSpawnAndVFXLoopingStoreOnRemoval)
		{
			VFXHolder vFXInstanceFromVFXHoldersAndRemoveItFromList = ReferenceSingleton<VFXHandler>.Instance.GetVFXInstanceFromVFXHoldersAndRemoveItFromList(effectOwner, this);
			if (vFXInstanceFromVFXHoldersAndRemoveItFromList != null)
			{
				GameObject vFXInstance = vFXInstanceFromVFXHoldersAndRemoveItFromList.VFXInstance;
				vFXInstance.GetComponent<ParticleEmissionController>().SetActive(value: false);
				ReferenceSingleton<PoolHandler>.Instance.StoreObject(vFXInstance, 4f);
			}
		}
	}

	public void SpawnEffectSecondVFX(GameObject effectOwner)
	{
		SpawnSecondVFX(GetVFXOwnerPosition(effectOwner), 5f);
	}

	[Button(null)]
	public void PlayGainEffectSFX()
	{
		if (enableInitializedVFXSpawnDelay)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, initializedVFXSpawnDelay, delegate
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(gainEffectSFX);
			});
		}
		else
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(gainEffectSFX);
		}
	}

	[Button(null)]
	public void PlayEffectActivationSFX()
	{
		if (enableEffectActivationSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(effectActivationSFX);
		}
	}

	[Button(null)]
	public void PlaySecondEffectActivationSFX()
	{
		if (enableSecondEffectActivationSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(secondEffectActivationSFX);
		}
	}

	public void PlayLoopableSFX()
	{
		if (enableLoopableSFX)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlayLoopableSFX(ref loopableEventInstance, loopableSFX);
		}
	}

	public void StopSFX()
	{
		ReferenceSingleton<SFXHandler>.Instance.StopSFX(ref loopableEventInstance);
	}
}
